      <HierarchicalLayout direction="top-down" spacing={[0.045, 0.045]} />
      <DiagramEnter fade />

      {/* Entry point */}
      <DiagramNode
        id="user"
        label="Users"
        icon="ui:users"
        shape="circle"
        color="#1a2040"
        size={[0.12, 0.12]}
      />

      {/* Frontend group */}
      <DiagramGroup id="frontend" label="Frontend" variant="boundary" color="#1a2040">
